            <div class="separator">✦</div>

             <!-- Tile 4: Placeholder Brand C -->
             <div class="brand-tile">
                <span style="color: #000; font-weight: 600; font-size: 18px;">AJIO</span>
           </div>

           <div class="separator">✦</div>

            <!-- Duplicate set for seamless loop -->
            <div class="brand-tile">
                <span class="logo-tira">tira</span>
            </div>

            <div class="separator">✦</div>

            <div class="brand-tile">
                <span style="color: #0058b9; font-weight: 800; font-size: 24px; font-style: italic;">IKEA</span>
            </div>

            <div class="separator">✦</div>

            <div class="brand-tile">
                 <span style="color: #e11d48; font-weight: bold; font-size: 20px;">RELIANCE</span>
